ON CONFLICT (slug) DO UPDATE SET
  title_lead    = EXCLUDED.title_lead,
  title_topic   = EXCLUDED.title_topic,
  summary       = EXCLUDED.summary,
  hero_image    = EXCLUDED.hero_image,
  hero_credit   = EXCLUDED.hero_credit,
  blocks        = EXCLUDED.blocks,
  external_url  = NULL,
  external_pubs = EXCLUDED.external_pubs,
  status        = 'published',
  published_at  = COALESCE(articles.published_at, now()),
  sort_order    = 0,
  updated_at    = now();

SELECT slug, status, sort_order, title_lead,
       jsonb_array_length(blocks) AS blocks, external_url
FROM articles WHERE slug = 'zman-kibbutz';
